mapper.sql:
WHERE employees.is_active = 1
AND employees.department_id = #{departmentId}
AND DATE(employees.start_working_date) <= DATE(#{payDate})
AND (
employees.id IN (
SELECT employee_id FROM employee_apply_status AS eas WHERE eas.is_active = 1 AND eas.employee_status_id NOT IN(2,5,6,8)
)
OR employees.id IN (
SELECT employee_id FROM employee_apply_status AS eas WHERE eas.is_active = 1
AND eas.employee_status_id IN (4,5,6)
AND MONTH(eas.date) > MONTH(#{payDate}) AND YEAR(eas.date) >= YEAR(#{payDate})
)
OR employees.id IN (
SELECT employee_id FROM payrolls WHERE is_active = 1 AND employee_id = employees.id AND pay_date = #{payDate}
)
)
AND employees.id NOT IN
(SELECT employee_id FROM employee_apply_status_histories
WHERE is_active = 1 AND employee_status_id = 2  AND date <= DATE_FORMAT(#{payDate}, "%Y-%m-01") AND date_to >= DATE_FORMAT(#{payDate}, "%Y-%m-28")
GROUP BY employee_apply_status_histories.employee_id)

