mapper.insert:
INSERT INTO payrolls ( employee_id, position_id, department_id, paid_type, bank_acc, bank_id, pay_date, old_salary, increase_salary, total_amount, note, created, created_by, is_active ) VALUES ( #{payroll.employeesId}, #{payroll.positionId}, #{payroll.departmentId}, #{payroll.paidType}, #{payroll.accountNumber}, #{payroll.accountId}, #{payroll.payDate}, #{payroll.currentSalary}, #{payroll.increaseSalary}, #{payroll.totalAmount}, #{payroll.note}, NOW(), #{payroll.createdBy}, #{payroll.isActive} );
INSERT INTO employee_history_salary ( employee_id, salary, increase_salary, date, created, created_by, is_active ) VALUES ( #{payroll.employeesId}, #{payroll.currentSalary}, #{payroll.increaseSalary}, #{payroll.payDate}, NOW(), #{payroll.createdBy}, 1 );
UPDATE employees SET current_salary = (#{payroll.currentSalary} + #{payroll.increaseSalary}), modified = NOW(), modified_by = #{payroll.modifiedBy} WHERE id = #{payroll.employeesId};

