mapper.insert:
UPDATE payroll_locks SET
                         is_lock = #{payrollLock.isLocked},
                         modified = NOW(),
                         modified_by = #{payrollLock.modifiedBy}
WHERE is_active = 1 AND department_id = #{payrollLock.departmentId}
    AND MONTH(pay_date) = MONTH(#{payrollLock.payDate}) AND YEAR(pay_date) = YEAR(#{payrollLock.payDate})

