SELECT
    IFNULL((SELECT is_lock FROM payroll_locks WHERE is_active = 1 AND department_id = #{departmentId}
                                                        AND MONTH(pay_date) = MONTH(#{payDate}) AND YEAR(pay_date) = YEAR(#{payDate})), 0)

